#[derive(Clone, Debug)]
pub struct EncodeOptions {
    pub encoding: Encoding,
    pub bom: bool,
    pub line_ending: LineEnding,
    pub ensure_trailing_newline: bool,
}

/// Pure. Converts \n to the requested ending and encodes. Fails on the first unmappable char.
pub fn encode(text: &ropey::Rope, opts: &EncodeOptions) -> Result<Vec<u8>, EncodeError>;

#[derive(Debug, PartialEq, Eq)]
pub enum EncodeError { Unmappable { line: u32, col: u32, ch: char } }

#[derive(Debug)]
pub struct Saved {
    pub bytes_written: u64,
    pub digest: [u8; 32],
    pub mtime: Option<std::time::SystemTime>,
}

/// Write to `<dir>/.<name>.katem5-<random>`, fsync, chmod to the target's mode if it exists, rename over target.
pub fn save(path: &std::path::Path, text: &ropey::Rope, opts: &EncodeOptions) -> Result<Saved, SaveError>;

#[derive(Debug)]
pub enum SaveError {
    Encode(EncodeError),
    Io { step: SaveStep, source: std::io::Error },
}

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum SaveStep { CreateTemp, Write, Sync, CopyMode, Rename }
